mapper.select:
SELECT 
FROM fin_ex_uploaded_document_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND id = #{id}
  AND status <> 'DELETED'

SELECT 
FROM fin_ex_uploaded_document_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND status <> 'DELETED'

  AND session_id = #{sessionId}


  AND (
        updated_at < #{cursorUpdatedAt}
        OR (updated_at = #{cursorUpdatedAt} AND id < #{cursorId})
      )

ORDER BY updated_at DESC, id DESC
LIMIT #{limit}
